  1	package com.pousada.marealta;
  2	
  3	import com.pousada.marealta.api.MessageController;
  4	import com.pousada.marealta.api.ReportController;
  5	import com.pousada.marealta.api.ReservationController;
  6	import com.pousada.marealta.api.RoomController;
  7	import com.pousada.marealta.infrastructure.Database;
  8	import com.pousada.marealta.infrastructure.MessageRepository;
  9	import com.pousada.marealta.infrastructure.ReservationRepository;
 10	import com.pousada.marealta.infrastructure.RoomRepository;
 11	import com.pousada.marealta.service.MessageService;
 12	import io.javalin.Javalin;
 13	import io.javalin.http.HttpStatus;
 14	
 15	public class Application {
 16	    public static void main(String[] args) {
 17	        String dbUrl = System.getenv("DB_URL");
 18	        String dbUser = System.getenv("DB_USER");
 19	        String dbPassword = System.getenv("DB_PASSWORD");
 20	        String portStr = System.getenv("PORT");
 21	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 22	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 23	        boolean copyToArchive = !"false".equalsIgnoreCase(System.getenv("COPY_TO_ARCHIVE"));
 24	
 25	        Database database = new Database(dbUrl, dbUser, dbPassword);
 26	        try {
 27	            database.initialize();
 28	        } catch (Exception e) {
 29	            System.err.println("Failed to initialize database: " + e.getMessage());
 30	            System.exit(1);
 31	        }
 32	
 33	        RoomRepository roomRepository = new RoomRepository(database);
 34	        ReservationRepository reservationRepository = new ReservationRepository(database);
 35	        MessageRepository messageRepository = new MessageRepository(database);
 36	        MessageService messageService = new MessageService(messageRepository, testMode, copyToArchive);
 37	
 38	        RoomController roomController = new RoomController(roomRepository);
 39	        ReservationController reservationController = new ReservationController(
 40	            reservationRepository, roomRepository, messageService);
 41	        MessageController messageController = new MessageController(messageRepository);
 42	        ReportController reportController = new ReportController(reservationRepository, roomRepository);
 43	
 44	        Javalin app = Javalin.create()
 45	            .exception(Exception.class, (e, ctx) -> {
 46	                e.printStackTrace();
 47	                ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
 48	            });
 49	
 50	        app.get("/rooms", roomController::getRooms);
 51	        app.post("/reservations", reservationController::createReservation);
 52	        app.get("/reservations/{id}", reservationController::getReservation);
 53	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 54	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 55	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 56	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 57	        app.get("/reservations/{id}/document", reservationController::getDocument);
 58	        app.get("/messages", messageController::getMessages);
 59	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 60	        app.get("/reports/revenue", reportController::getRevenueReport);
 61	
 62	        app.start(port);
 63	        System.out.println("Pousada Maré Alta API running on port " + port);
 64	    }
 65	}
 66	package com.pousada.marealta.api;
 67	
 68	import com.google.gson.JsonObject;
 69	import com.pousada.marealta.domain.Document;
 70	import com.pousada.marealta.domain.Message;
 71	import com.pousada.marealta.domain.MessageStatus;
 72	import com.pousada.marealta.domain.RatePlan;
 73	import com.pousada.marealta.domain.Reservation;
 74	import com.pousada.marealta.domain.ReservationStatus;
 75	import com.pousada.marealta.domain.Room;
 76	import com.pousada.marealta.infrastructure.MessageRepository;
 77	import com.pousada.marealta.infrastructure.ReservationRepository;
 78	import com.pousada.marealta.infrastructure.RoomRepository;
 79	import com.pousada.marealta.service.MessageService;
 80	import com.pousada.marealta.service.PriceCalculator;
 81	import com.pousada.marealta.service.PricingStrategy;
 82	import com.pousada.marealta.service.ReservationState;
 83	import com.pousada.marealta.service.ReservationStateMachine;
 84	import io.javalin.http.Context;
 85	import io.javalin.http.HttpStatus;
 86	import java.math.BigDecimal;
 87	import java.time.LocalDate;
 88	import java.time.format.DateTimeFormatter;
 89	import java.util.Optional;
 90	
 91	public class ReservationController {
 92	    private final ReservationRepository reservationRepository;
 93	    private final RoomRepository roomRepository;
 94	    private final MessageService messageService;
 95	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 96	
 97	    public ReservationController(ReservationRepository reservationRepository,
 98	                                RoomRepository roomRepository,
 99	                                MessageService messageService) {
100	        this.reservationRepository = reservationRepository;
101	        this.roomRepository = roomRepository;
102	        this.messageService = messageService;
103	    }
104	
105	    public void createReservation(Context ctx) throws Exception {
106	        String bodyStr = ctx.body();
107	        JsonObject body = com.google.gson.JsonParser.parseString(bodyStr).getAsJsonObject();
108	
109	        if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
110	            !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
111	            !body.has("guests") || !body.has("ratePlan")) {
112	            JsonObject error = new JsonObject();
113	            error.addProperty("error", "INVALID_REQUEST");
114	            error.addProperty("message", "Missing required fields");
115	            ctx.status(HttpStatus.BAD_REQUEST);
116	            ctx.json(error);
117	            return;
118	        }
119	
120	        int roomNumber = body.getAsJsonPrimitive("roomNumber").getAsInt();
121	        String guestName = body.getAsJsonPrimitive("guestName").getAsString();
122	        String guestEmail = body.getAsJsonPrimitive("guestEmail").getAsString();
123	        String guestCpf = body.getAsJsonPrimitive("guestCpf").getAsString();
124	        LocalDate checkIn = LocalDate.parse(body.getAsJsonPrimitive("checkIn").getAsString(), DATE_FORMATTER);
125	        LocalDate checkOut = LocalDate.parse(body.getAsJsonPrimitive("checkOut").getAsString(), DATE_FORMATTER);
126	        int guests = body.getAsJsonPrimitive("guests").getAsInt();
127	        String ratePlan = body.getAsJsonPrimitive("ratePlan").getAsString();
128	
129	        Optional<Room> room = roomRepository.findByNumber(roomNumber);
130	        if (room.isEmpty()) {
131	            JsonObject error = new JsonObject();
132	            error.addProperty("error", "ROOM_NOT_FOUND");
133	            error.addProperty("message", "Room not found");
134	            ctx.status(HttpStatus.NOT_FOUND);
135	            ctx.json(error);
136	            return;
137	        }
138	
139	        if (guests < 1 || guests > room.get().getCapacity()) {
140	            JsonObject error = new JsonObject();
141	            error.addProperty("error", "CAPACITY_EXCEEDED");
142	            error.addProperty("message", "Number of guests exceeds room capacity");
143	            ctx.status(422);
144	            ctx.json(error);
145	            return;
146	        }
147	
148	        if (!checkIn.isBefore(checkOut)) {
149	            JsonObject error = new JsonObject();
150	            error.addProperty("error", "INVALID_REQUEST");
151	            error.addProperty("message", "Check-in must be before check-out");
152	            ctx.status(HttpStatus.BAD_REQUEST);
153	            ctx.json(error);
154	            return;
155	        }
156	
157	        if (!reservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
158	            JsonObject error = new JsonObject();
159	            error.addProperty("error", "ROOM_UNAVAILABLE");
160	            error.addProperty("message", "Room is not available for the selected dates");
161	            ctx.status(HttpStatus.CONFLICT);
162	            ctx.json(error);
163	            return;
164	        }
165	
166	        PricingStrategy pricingStrategy = "NON_REFUNDABLE".equals(ratePlan) ?
167	            new com.pousada.marealta.service.NonRefundablePricingStrategy() :
168	            new com.pousada.marealta.service.StandardPricingStrategy();
169	        PriceCalculator priceCalculator = new PriceCalculator(pricingStrategy);
170	        PriceCalculator.PriceBreakdown pricing = priceCalculator.calculatePrice(
171	            room.get(), checkIn, checkOut);
172	
173	        Reservation reservation = new Reservation();
174	        reservation.setRoomNumber(roomNumber);
175	        reservation.setGuestName(guestName);
176	        reservation.setGuestEmail(guestEmail);
177	        reservation.setGuestCpf(guestCpf);
178	        reservation.setCheckIn(checkIn);
179	        reservation.setCheckOut(checkOut);
180	        reservation.setGuests(guests);
181	        reservation.setRatePlan(RatePlan.valueOf(ratePlan));
182	        reservation.setNights(pricing.nights);
183	        reservation.setSubtotal(pricing.subtotal);
184	        reservation.setDiscount(pricing.discount);
185	        reservation.setTotal(pricing.total);
186	        reservation.setStatus(ReservationStatus.PENDING);
187	        reservation.setAmountPaid(BigDecimal.ZERO);
188	
189	        reservation = reservationRepository.create(reservation);
190	
191	        ctx.status(HttpStatus.CREATED);
192	        ctx.json(mapReservationToJson(reservation));
193	    }
194	
195	    public void getReservation(Context ctx) throws Exception {
196	        Long id = ctx.pathParamAsClass("id", Long.class).get();
197	        Optional<Reservation> reservation = reservationRepository.findById(id);
198	
199	        if (reservation.isEmpty()) {
200	            JsonObject error = new JsonObject();
201	            error.addProperty("error", "RESERVATION_NOT_FOUND");
202	            error.addProperty("message", "Reservation not found");
203	            ctx.status(HttpStatus.NOT_FOUND);
204	            ctx.json(error);
205	            return;
206	        }
207	
208	        ctx.json(mapReservationToJson(reservation.get()));
209	    }
210	
211	    public void confirmReservation(Context ctx) throws Exception {
212	        Long id = ctx.pathParamAsClass("id", Long.class).get();
213	        Optional<Reservation> reservation = reservationRepository.findById(id);
214	
215	        if (reservation.isEmpty()) {
216	            JsonObject error = new JsonObject();
217	            error.addProperty("error", "RESERVATION_NOT_FOUND");
218	            error.addProperty("message", "Reservation not found");
219	            ctx.status(HttpStatus.NOT_FOUND);
220	            ctx.json(error);
221	            return;
222	        }
223	
224	        Reservation res = reservation.get();
225	        ReservationState state = ReservationStateMachine.getState(res.getStatus());
226	
227	        try {
228	            res = state.confirm(res);
229	            reservationRepository.update(res);
230	
231	            Message message = createConfirmationEmail(res);
232	            messageService.sendAndStoreMessage(message);
233	        } catch (IllegalStateException e) {
234	            JsonObject error = new JsonObject();
235	            error.addProperty("error", "OPERATION_NOT_ALLOWED");
236	            error.addProperty("message", e.getMessage());
237	            ctx.status(HttpStatus.CONFLICT);
238	            ctx.json(error);
239	            return;
240	        }
241	
242	        ctx.json(mapReservationToJson(res));
243	    }
244	
245	    public void cancelReservation(Context ctx) throws Exception {
246	        Long id = ctx.pathParamAsClass("id", Long.class).get();
247	        Optional<Reservation> reservation = reservationRepository.findById(id);
248	
249	        if (reservation.isEmpty()) {
250	            JsonObject error = new JsonObject();
251	            error.addProperty("error", "RESERVATION_NOT_FOUND");
252	            error.addProperty("message", "Reservation not found");
253	            ctx.status(HttpStatus.NOT_FOUND);
254	            ctx.json(error);
255	            return;
256	        }
257	
258	        Reservation res = reservation.get();
259	        ReservationState state = ReservationStateMachine.getState(res.getStatus());
260	
261	        try {
262	            res = state.cancel(res);
263	            reservationRepository.update(res);
264	        } catch (IllegalStateException e) {
265	            JsonObject error = new JsonObject();
266	            error.addProperty("error", "OPERATION_NOT_ALLOWED");
267	            error.addProperty("message", e.getMessage());
268	            ctx.status(HttpStatus.CONFLICT);
269	            ctx.json(error);
270	            return;
271	        }
272	
273	        ctx.json(mapReservationToJson(res));
274	    }
