307	    public void checkOut(Context ctx) throws Exception {
308	        Long id = ctx.pathParamAsClass("id", Long.class).get();
309	        Optional<Reservation> reservation = reservationRepository.findById(id);
310	
311	        if (reservation.isEmpty()) {
312	            JsonObject error = new JsonObject();
313	            error.addProperty("error", "RESERVATION_NOT_FOUND");
314	            error.addProperty("message", "Reservation not found");
315	            ctx.status(HttpStatus.NOT_FOUND);
316	            ctx.json(error);
317	            return;
318	        }
319	
320	        Reservation res = reservation.get();
321	        ReservationState state = ReservationStateMachine.getState(res.getStatus());
322	
323	        try {
324	            res = state.checkOut(res);
325	            reservationRepository.update(res);
326	        } catch (IllegalStateException e) {
327	            JsonObject error = new JsonObject();
328	            error.addProperty("error", "OPERATION_NOT_ALLOWED");
329	            error.addProperty("message", e.getMessage());
330	            ctx.status(HttpStatus.CONFLICT);
331	            ctx.json(error);
332	            return;
333	        }
334	
335	        ctx.json(mapDocumentToJson(createDocument(res)));
336	    }
337	
338	    public void getDocument(Context ctx) throws Exception {
339	        Long id = ctx.pathParamAsClass("id", Long.class).get();
340	        Optional<Reservation> reservation = reservationRepository.findById(id);
341	
342	        if (reservation.isEmpty()) {
343	            JsonObject error = new JsonObject();
344	            error.addProperty("error", "RESERVATION_NOT_FOUND");
345	            error.addProperty("message", "Reservation not found");
346	            ctx.status(HttpStatus.NOT_FOUND);
347	            ctx.json(error);
348	            return;
349	        }
350	
351	        if (reservation.get().getAmountPaid().compareTo(BigDecimal.ZERO) <= 0) {
352	            JsonObject error = new JsonObject();
353	            error.addProperty("error", "OPERATION_NOT_ALLOWED");
354	            error.addProperty("message", "No document available for unpaid reservations");
355	            ctx.status(HttpStatus.CONFLICT);
356	            ctx.json(error);
357	            return;
358	        }
359	
360	        ctx.json(mapDocumentToJson(createDocument(reservation.get())));
361	    }
