363	    private Message createConfirmationEmail(Reservation res) throws Exception {
364	        Optional<Room> room = roomRepository.findByNumber(res.getRoomNumber());
365	        String roomType = room.map(r -> r.getType().getLabel()).orElse("UNKNOWN");
366	
367	        Document doc = createDocument(res);
368	        String docText = formatDocument(doc);
369	
370	        String body = """
371	                Olá, %s!
372	
373	                Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
374	
375	                %s
376	
377	                A entrada é a partir das 14h, e a saída, até as 12h.
378	                Até breve!
379	                """.formatted(res.getGuestName(), docText);
380	
381	        return new Message("EMAIL", res.getGuestEmail(),
382	            "Reserva confirmada - Pousada Maré Alta", body, MessageStatus.SENT);
383	    }
384	
385	    private Document createDocument(Reservation res) throws Exception {
386	        Optional<Room> room = roomRepository.findByNumber(res.getRoomNumber());
387	        String roomType = room.map(r -> r.getType().getLabel()).orElse("UNKNOWN");
388	
389	        return new Document(res.getId(), res.getGuestName(), res.getGuestCpf(),
390	            res.getRoomNumber(), roomType, res.getCheckIn(), res.getCheckOut(),
391	            res.getNights(), res.getSubtotal(), res.getDiscount(), res.getTotal());
392	    }
393	
394	    private String formatDocument(Document doc) {
395	        String nightsLabel = doc.getNights() == 1 ? "1 diária" : doc.getNights() + " diárias";
396	        String discountLine = doc.getDiscount().compareTo(BigDecimal.ZERO) > 0 ?
397	            "Desconto: R$ " + formatCurrency(doc.getDiscount()) + "\n" : "";
398	
399	        return """
400	                Comprovante de reserva nº %d
401	                Hóspede: %s (CPF %s)
402	                Quarto: %d (%s)
403	                Entrada: %s | Saída: %s | %s
404	                Diárias: R$ %s
405	                %sTotal: R$ %s
406	                """.formatted(
407	                doc.getReservationId(),
408	                doc.getGuestName(),
409	                formatCPF(doc.getGuestCpf()),
410	                doc.getRoomNumber(),
411	                doc.getRoomType(),
412	                formatDate(doc.getCheckIn()),
413	                formatDate(doc.getCheckOut()),
414	                nightsLabel,
415	                formatCurrency(doc.getSubtotal()),
416	                discountLine,
417	                formatCurrency(doc.getTotal()));
418	    }
419	
420	    private String formatCurrency(BigDecimal value) {
421	        return String.format("%.2f", value).replace(".", ",");
422	    }
423	
424	    private String formatCPF(String cpf) {
425	        if (cpf.length() != 11) return cpf;
426	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
427	               cpf.substring(6, 9) + "-" + cpf.substring(9);
428	    }
429	
430	    private String formatDate(LocalDate date) {
431	        return date.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));
432	    }
433	
434	    private JsonObject mapReservationToJson(Reservation res) {
435	        JsonObject obj = new JsonObject();
436	        obj.addProperty("id", res.getId());
437	        obj.addProperty("roomNumber", res.getRoomNumber());
438	        obj.addProperty("guestName", res.getGuestName());
439	        obj.addProperty("guestEmail", res.getGuestEmail());
440	        obj.addProperty("guestCpf", res.getGuestCpf());
441	        obj.addProperty("checkIn", res.getCheckIn().toString());
442	        obj.addProperty("checkOut", res.getCheckOut().toString());
443	        obj.addProperty("guests", res.getGuests());
444	        obj.addProperty("ratePlan", res.getRatePlan().getLabel());
445	        obj.addProperty("nights", res.getNights());
446	        obj.addProperty("subtotal", res.getSubtotal().doubleValue());
447	        obj.addProperty("discount", res.getDiscount().doubleValue());
448	        obj.addProperty("total", res.getTotal().doubleValue());
449	        obj.addProperty("status", res.getStatus().name());
450	        obj.addProperty("amountPaid", res.getAmountPaid().doubleValue());
451	        if (res.getRefund() != null) {
452	            obj.addProperty("refund", res.getRefund().doubleValue());
453	        } else {
454	            obj.add("refund", null);
455	        }
456	        return obj;
457	    }
458	
459	    private JsonObject mapDocumentToJson(Document doc) {
460	        JsonObject obj = new JsonObject();
461	        obj.addProperty("title", doc.getTitle());
462	        obj.addProperty("reservationId", doc.getReservationId());
463	        obj.addProperty("guestName", doc.getGuestName());
464	        obj.addProperty("guestCpf", doc.getGuestCpf());
465	        obj.addProperty("roomNumber", doc.getRoomNumber());
466	        obj.addProperty("roomType", doc.getRoomType());
467	        obj.addProperty("checkIn", doc.getCheckIn().toString());
468	        obj.addProperty("checkOut", doc.getCheckOut().toString());
469	        obj.addProperty("nights", doc.getNights());
470	        obj.addProperty("subtotal", doc.getSubtotal().doubleValue());
471	        obj.addProperty("discount", doc.getDiscount().doubleValue());
472	        obj.addProperty("total", doc.getTotal().doubleValue());
473	        return obj;
474	    }
475	}

