 91	public class ReservationController {
 92	    private final ReservationRepository reservationRepository;
 93	    private final RoomRepository roomRepository;
 94	    private final MessageService messageService;
 95	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 96	
 97	    public ReservationController(ReservationRepository reservationRepository,
 98	                                RoomRepository roomRepository,
 99	                                MessageService messageService) {
100	        this.reservationRepository = reservationRepository;
101	        this.roomRepository = roomRepository;
102	        this.messageService = messageService;
103	    }
104	
105	    public void createReservation(Context ctx) throws Exception {
106	        String bodyStr = ctx.body();
107	        JsonObject body = com.google.gson.JsonParser.parseString(bodyStr).getAsJsonObject();
108	
109	        if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
110	            !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
111	            !body.has("guests") || !body.has("ratePlan")) {
112	            JsonObject error = new JsonObject();
113	            error.addProperty("error", "INVALID_REQUEST");
114	            error.addProperty("message", "Missing required fields");
115	            ctx.status(HttpStatus.BAD_REQUEST);
116	            ctx.json(error);
117	            return;
118	        }
119	
120	        int roomNumber = body.getAsJsonPrimitive("roomNumber").getAsInt();
121	        String guestName = body.getAsJsonPrimitive("guestName").getAsString();
122	        String guestEmail = body.getAsJsonPrimitive("guestEmail").getAsString();
123	        String guestCpf = body.getAsJsonPrimitive("guestCpf").getAsString();
124	        LocalDate checkIn = LocalDate.parse(body.getAsJsonPrimitive("checkIn").getAsString(), DATE_FORMATTER);
125	        LocalDate checkOut = LocalDate.parse(body.getAsJsonPrimitive("checkOut").getAsString(), DATE_FORMATTER);
126	        int guests = body.getAsJsonPrimitive("guests").getAsInt();
127	        String ratePlan = body.getAsJsonPrimitive("ratePlan").getAsString();
128	
129	        Optional<Room> room = roomRepository.findByNumber(roomNumber);
130	        if (room.isEmpty()) {
131	            JsonObject error = new JsonObject();
132	            error.addProperty("error", "ROOM_NOT_FOUND");
133	            error.addProperty("message", "Room not found");
134	            ctx.status(HttpStatus.NOT_FOUND);
135	            ctx.json(error);
136	            return;
137	        }
138	
139	        if (guests < 1 || guests > room.get().getCapacity()) {
140	            JsonObject error = new JsonObject();
141	            error.addProperty("error", "CAPACITY_EXCEEDED");
142	            error.addProperty("message", "Number of guests exceeds room capacity");
143	            ctx.status(422);
144	            ctx.json(error);
145	            return;
146	        }
147	
148	        if (!checkIn.isBefore(checkOut)) {
149	            JsonObject error = new JsonObject();
150	            error.addProperty("error", "INVALID_REQUEST");
151	            error.addProperty("message", "Check-in must be before check-out");
152	            ctx.status(HttpStatus.BAD_REQUEST);
153	            ctx.json(error);
154	            return;
155	        }
156	
157	        if (!reservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
158	            JsonObject error = new JsonObject();
159	            error.addProperty("error", "ROOM_UNAVAILABLE");
160	            error.addProperty("message", "Room is not available for the selected dates");
161	            ctx.status(HttpStatus.CONFLICT);
162	            ctx.json(error);
163	            return;
164	        }
165	
166	        PricingStrategy pricingStrategy = "NON_REFUNDABLE".equals(ratePlan) ?
167	            new com.pousada.marealta.service.NonRefundablePricingStrategy() :
168	            new com.pousada.marealta.service.StandardPricingStrategy();
169	        PriceCalculator priceCalculator = new PriceCalculator(pricingStrategy);
170	        PriceCalculator.PriceBreakdown pricing = priceCalculator.calculatePrice(
171	            room.get(), checkIn, checkOut);
172	
173	        Reservation reservation = new Reservation();
174	        reservation.setRoomNumber(roomNumber);
175	        reservation.setGuestName(guestName);
176	        reservation.setGuestEmail(guestEmail);
177	        reservation.setGuestCpf(guestCpf);
178	        reservation.setCheckIn(checkIn);
179	        reservation.setCheckOut(checkOut);
180	        reservation.setGuests(guests);
181	        reservation.setRatePlan(RatePlan.valueOf(ratePlan));
182	        reservation.setNights(pricing.nights);
183	        reservation.setSubtotal(pricing.subtotal);
184	        reservation.setDiscount(pricing.discount);
185	        reservation.setTotal(pricing.total);
186	        reservation.setStatus(ReservationStatus.PENDING);
187	        reservation.setAmountPaid(BigDecimal.ZERO);
188	
189	        reservation = reservationRepository.create(reservation);
190	
191	        ctx.status(HttpStatus.CREATED);
192	        ctx.json(mapReservationToJson(reservation));
193	    }
194	
195	    public void getReservation(Context ctx) throws Exception {
196	        Long id = ctx.pathParamAsClass("id", Long.class).get();
197	        Optional<Reservation> reservation = reservationRepository.findById(id);
