211	    public void confirmReservation(Context ctx) throws Exception {
212	        Long id = ctx.pathParamAsClass("id", Long.class).get();
213	        Optional<Reservation> reservation = reservationRepository.findById(id);
214	
215	        if (reservation.isEmpty()) {
216	            JsonObject error = new JsonObject();
