221	            return;
222	        }
223	
224	        Reservation res = reservation.get();
225	        ReservationState state = ReservationStateMachine.getState(res.getStatus());
226	
227	        try {
228	            res = state.confirm(res);
229	            reservationRepository.update(res);
230	
231	            Message message = createConfirmationEmail(res);
232	            messageService.sendAndStoreMessage(message);
233	        } catch (IllegalStateException e) {
234	            JsonObject error = new JsonObject();
235	            error.addProperty("error", "OPERATION_NOT_ALLOWED");
236	            error.addProperty("message", e.getMessage());
237	            ctx.status(HttpStatus.CONFLICT);
238	            ctx.json(error);
239	            return;
240	        }
241	
242	        ctx.json(mapReservationToJson(res));
243	    }
