     1	package com.pousada.marealta.service;
     2	
     3	public class EmailValidator {
     4	    public static boolean isValid(String email) {
     5	        if (email == null || email.trim().isEmpty()) {
     6	            return false;
     7	        }
     8	
     9	        int atCount = 0;
    10	        int atIndex = -1;
    11	        for (int i = 0; i < email.length(); i++) {
    12	            if (email.charAt(i) == '@') {
    13	                atCount++;
    14	                atIndex = i;
    15	            }
    16	        }
    17	
    18	        if (atCount != 1) {
    19	            return false;
    20	        }
    21	
    22	        String beforeAt = email.substring(0, atIndex);
    23	        String afterAt = email.substring(atIndex + 1);
    24	
    25	        if (beforeAt.isEmpty()) {
    26	            return false;
    27	        }
    28	
    29	        if (afterAt.isEmpty()) {
    30	            return false;
    31	        }
    32	
    33	        int dotCount = 0;
    34	        for (int i = 0; i < afterAt.length(); i++) {
    35	            if (afterAt.charAt(i) == '.') {
    36	                dotCount++;
    37	            }
    38	        }
    39	
    40	        if (dotCount == 0) {
    41	            return false;
    42	        }
    43	
    44	        if (afterAt.startsWith(".") || afterAt.endsWith(".")) {
