     7	
     8	public class PriceCalculator {
     9	    private final PricingStrategy pricingStrategy;
    10	
    11	    public PriceCalculator(PricingStrategy pricingStrategy) {
    12	        this.pricingStrategy = pricingStrategy;
    13	    }
    14	
    15	    public static BigDecimal round(BigDecimal value) {
    16	        return value.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    public static boolean isHighSeason(LocalDate date) {
    20	        int month = date.getMonthValue();
    21	        int day = date.getDayOfMonth();
    22	
    23	        if (month == 7) {
    24	            return true;
    25	        }
    26	
    27	        if (month == 12 && day >= 15) {
    28	            return true;
    29	        }
    30	        if (month == 1 || month == 2) {
    31	            return true;
    32	        }
    33	
    34	        return false;
    35	    }
    36	
    37	    public PriceBreakdown calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut) {
    38	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    39	
    40	        BigDecimal subtotal = BigDecimal.ZERO;
    41	        LocalDate current = checkIn;
    42	        while (current.isBefore(checkOut)) {
    43	            BigDecimal nightlyRate = pricingStrategy.calculateNightRate(room, current);
    44	            subtotal = subtotal.add(nightlyRate);
    45	            current = current.plusDays(1);
    46	        }
    47	        subtotal = round(subtotal);
    48	
    49	        BigDecimal discount = pricingStrategy.calculateDiscount(subtotal);
    50	        discount = round(discount);
    51	
    52	        BigDecimal total = round(subtotal.subtract(discount));
    53	
    54	        return new PriceBreakdown(nights, subtotal, discount, total);
    55	    }
    56	
    57	    public static class PriceBreakdown {
    58	        public int nights;
    59	        public BigDecimal subtotal;
    60	        public BigDecimal discount;
    61	        public BigDecimal total;
    62	
    63	        public PriceBreakdown(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    64	            this.nights = nights;
    65	            this.subtotal = subtotal;
    66	            this.discount = discount;
    67	            this.total = total;
    68	        }
    69	    }
    70	}
