    24	    public Reservation create(Reservation reservation) throws SQLException {
    25	        String sql = """
    26	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
    27	                    check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status)
    28	                VALUES (%d, '%s', '%s', '%s', '%s', '%s', %d, '%s', %d, %s, %s, %s, '%s')
    29	                """.formatted(
    30	                reservation.getRoomNumber(),
    31	                escape(reservation.getGuestName()),
    32	                escape(reservation.getGuestEmail()),
    33	                escape(reservation.getGuestCpf()),
    34	                reservation.getCheckIn(),
    35	                reservation.getCheckOut(),
    36	                reservation.getGuests(),
    37	                reservation.getRatePlan().name(),
    38	                reservation.getNights(),
    39	                reservation.getSubtotal(),
    40	                reservation.getDiscount(),
    41	                reservation.getTotal(),
    42	                reservation.getStatus().name());
    43	
    44	        try (Connection conn = database.getConnection();
    45	             Statement stmt = conn.createStatement()) {
    46	            stmt.executeUpdate(sql, Statement.RETURN_GENERATED_KEYS);
    47	            ResultSet rs = stmt.getGeneratedKeys();
    48	            if (rs.next()) {
    49	                reservation.setId(rs.getLong(1));
    50	            }
    51	        }
    52	        return reservation;
    53	    }
