    85	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    86	        String sql = """
    87	                SELECT COUNT(*) as count FROM reservations
    88	                WHERE room_number = %d
    89	                AND status != 'CANCELLED'
    90	                AND check_in < '%s' AND check_out > '%s'
